/* Layer 3 biases (4) */
static const float layer3_biases[4] = {
    0.07629096f, 0.09814270f, -0.02004522f, 0.00420647f
};

/* Forward pass through the network */
void forward(const float* input, float* output) {
    float buffer1[64];
    float buffer2[64];
    float* current = buffer1;
    float* next = buffer2;
    float* temp;

    memcpy(current, input, INPUT_DIM * sizeof(float));

    /* Layer 0: 20 -> 64 */
    linear(current, next, layer0_weights, layer0_biases, 20, 64);
    relu(next, 64);
    temp = current; current = next; next = temp;

    /* Layer 1: 64 -> 64 */
    linear(current, next, layer1_weights, layer1_biases, 64, 64);
    relu(next, 64);
    temp = current; current = next; next = temp;

    /* Layer 2: 64 -> 64 */
    linear(current, next, layer2_weights, layer2_biases, 64, 64);
    relu(next, 64);
    temp = current; current = next; next = temp;

    /* Layer 3: 64 -> 4 */
    linear(current, next, layer3_weights, layer3_biases, 64, 4);
    clip(next, 4);

    memcpy(output, next, OUTPUT_DIM * sizeof(float));
}
